        jurisdiction: plain(data.jurisdiction, "the country or jurisdiction", 200, required),
        legalBasis: plain(data.legalBasis, "the law or legal basis", 1000, required),
        noticeObligation: plain(data.noticeObligation, "the law and provision requiring Templ to accept this notice", 1000, reason === "mandatory-notice"),
        evidence: plain(data.evidence, "the exact content location and supporting facts or references", 1500, required),
        reporterName: plain(data.reporterName, "your name or organization", 200, required),
        contactEmail: email,
